#include <stdio.h>

int main(void) {
    int a, b, c;
    if (scanf("%d %d %d", &a, &b, &c) != 3) {
        puts("Expected three integer marks.");
        return 1;
    }
    if (a < 0 || a > 100 || b < 0 || b > 100 || c < 0 || c > 100) {
        puts("Marks must be between 0 and 100.");
        return 1;
    }
    double average = (a + b + c) / 3.0;
    printf("Average: %.2f\n", average);
    return 0;
}
